"""Frozen T35 additive revision proposals, decisions and accepted relations."""

from alembic import op

revision = "0001_revisions_t35"
down_revision = None
branch_labels = None
depends_on = None


def upgrade():
    op.execute("CREATE TABLE revision_proposals (\n\tid UUID NOT NULL, \n\towner_user_id UUID NOT NULL, \n\tis_synthetic BOOLEAN NOT NULL, \n\told_plan_id UUID NOT NULL, \n\tnew_plan_id UUID NOT NULL, \n\told_source_version_id UUID NOT NULL, \n\tnew_source_version_id UUID NOT NULL, \n\told_proposal_id UUID NOT NULL, \n\tnew_proposal_id UUID NOT NULL, \n\texpected_old_state_version INTEGER NOT NULL, \n\texpected_new_state_version INTEGER NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tpayload_sha256 VARCHAR(64) NOT NULL, \n\tpayload JSONB NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\taudit_event_id UUID NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_revision_natural_request UNIQUE (owner_user_id, request_sha256), \n\tCONSTRAINT uq_revision_relationship_scope UNIQUE (id, old_plan_id, new_plan_id, owner_user_id, is_synthetic), \n\tCONSTRAINT fk_revision_old_owner FOREIGN KEY(old_plan_id, old_source_version_id, owner_user_id, is_synthetic) REFERENCES plan_execution_heads (plan_id, source_version_id, owner_user_id, is_synthetic) ON DELETE RESTRICT, \n\tCONSTRAINT fk_revision_new_owner FOREIGN KEY(new_plan_id, new_source_version_id, owner_user_id, is_synthetic) REFERENCES plan_execution_heads (plan_id, source_version_id, owner_user_id, is_synthetic) ON DELETE RESTRICT, \n\tCONSTRAINT fk_revision_old_proposal FOREIGN KEY(old_proposal_id, old_plan_id) REFERENCES plan_execution_proposals (id, plan_id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_revision_new_proposal FOREIGN KEY(new_proposal_id, new_plan_id) REFERENCES plan_execution_proposals (id, plan_id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_revision_distinct_pins CHECK (old_plan_id<>new_plan_id AND expected_old_state_version BETWEEN 2 AND 2147483647 AND expected_new_state_version BETWEEN 1 AND 2147483647), \n\tCONSTRAINT ck_revision_hashes CHECK (length(request_sha256)=64 AND request_sha256 ~ '^[0-9a-f]{64}$' AND length(payload_sha256)=64 AND payload_sha256 ~ '^[0-9a-f]{64}$'), \n\tCONSTRAINT ck_revision_payload CHECK (jsonb_typeof(payload)='object' AND octet_length(payload::text)<=2097152), \n\tCONSTRAINT ck_revision_retention CHECK (expires_at>created_at AND expires_at<=(((created_at AT TIME ZONE 'UTC')+interval '24 months') AT TIME ZONE 'UTC'))\n)")
    op.execute('CREATE INDEX ix_revision_owner_created ON revision_proposals (owner_user_id, created_at, id)')
    op.execute("CREATE TABLE revision_decisions (\n\tid UUID NOT NULL, \n\trevision_id UUID NOT NULL, \n\told_plan_id UUID NOT NULL, \n\tnew_plan_id UUID NOT NULL, \n\towner_user_id UUID NOT NULL, \n\tis_synthetic BOOLEAN NOT NULL, \n\taction VARCHAR(8) NOT NULL, \n\trevision_version INTEGER NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tdecided_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\taudit_event_id UUID NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_revision_single_decision UNIQUE (revision_id), \n\tCONSTRAINT uq_revision_decision_scope UNIQUE (id, revision_id, old_plan_id, new_plan_id, owner_user_id, is_synthetic), \n\tCONSTRAINT uq_revision_decision_action_scope UNIQUE (id, revision_id, old_plan_id, new_plan_id, owner_user_id, is_synthetic, action), \n\tCONSTRAINT fk_revision_decision_scope FOREIGN KEY(revision_id, old_plan_id, new_plan_id, owner_user_id, is_synthetic) REFERENCES revision_proposals (id, old_plan_id, new_plan_id, owner_user_id, is_synthetic) ON DELETE RESTRICT, \n\tCONSTRAINT ck_revision_decision CHECK (action IN ('accept','reject') AND revision_version=2), \n\tCONSTRAINT ck_revision_decision_hash CHECK (length(request_sha256)=64 AND request_sha256 ~ '^[0-9a-f]{64}$'), \n\tCONSTRAINT ck_revision_decision_retention CHECK (expires_at>decided_at AND expires_at<=(((decided_at AT TIME ZONE 'UTC')+interval '24 months') AT TIME ZONE 'UTC'))\n)")
    op.execute("CREATE TABLE plan_replacement_links (\n\tid UUID NOT NULL, \n\trevision_id UUID NOT NULL, \n\tdecision_id UUID NOT NULL, \n\told_plan_id UUID NOT NULL, \n\tnew_plan_id UUID NOT NULL, \n\towner_user_id UUID NOT NULL, \n\tis_synthetic BOOLEAN NOT NULL, \n\taction VARCHAR(8) NOT NULL, \n\taccepted_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\texpires_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\taudit_event_id UUID NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_revision_old_successor UNIQUE (old_plan_id), \n\tCONSTRAINT uq_revision_new_predecessor UNIQUE (new_plan_id), \n\tCONSTRAINT uq_revision_single_relationship UNIQUE (revision_id), \n\tCONSTRAINT fk_revision_accepted_decision FOREIGN KEY(decision_id, revision_id, old_plan_id, new_plan_id, owner_user_id, is_synthetic, action) REFERENCES revision_decisions (id, revision_id, old_plan_id, new_plan_id, owner_user_id, is_synthetic, action) ON DELETE RESTRICT, \n\tCONSTRAINT ck_revision_relationship_distinct CHECK (old_plan_id<>new_plan_id AND action='accept'), \n\tCONSTRAINT ck_revision_relationship_retention CHECK (expires_at>accepted_at AND expires_at<=(((accepted_at AT TIME ZONE 'UTC')+interval '24 months') AT TIME ZONE 'UTC'))\n)")
    op.execute("CREATE FUNCTION revisions_reject_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Revision history cannot be changed' USING ERRCODE='23514'; END $$")
    op.execute('CREATE TRIGGER revision_proposals_no_update BEFORE UPDATE ON revision_proposals FOR EACH ROW EXECUTE FUNCTION revisions_reject_update()')
    op.execute('CREATE TRIGGER revision_decisions_no_update BEFORE UPDATE ON revision_decisions FOR EACH ROW EXECUTE FUNCTION revisions_reject_update()')
    op.execute('CREATE TRIGGER plan_replacement_links_no_update BEFORE UPDATE ON plan_replacement_links FOR EACH ROW EXECUTE FUNCTION revisions_reject_update()')


def downgrade():
    op.execute('DROP TRIGGER plan_replacement_links_no_update ON plan_replacement_links')
    op.execute('DROP TRIGGER revision_decisions_no_update ON revision_decisions')
    op.execute('DROP TRIGGER revision_proposals_no_update ON revision_proposals')
    op.execute("DROP FUNCTION revisions_reject_update()")
    op.drop_table('plan_replacement_links')
    op.drop_table('revision_decisions')
    op.drop_table('revision_proposals')
